from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    holes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                edge |= y in (0, h - 1) or x in (0, w - 1)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not edge:
                holes.append(comp)
    out = [row[:] for row in grid]
    for comp in sorted(holes, key=len, reverse=True)[:2]:
        for y, x in comp:
            out[y][x] = 4
    return out
