            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j - i >= 2:
                ans.append((color, i, j))
            i = j
        return ans

    candidates = []
    top, bottom = runs(grid[0]), runs(grid[-1])
    for a in top:
        for b in bottom:
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                candidates.append(('tb', a, b))
    left = runs([grid[r][0] for r in range(h)])
    right = runs([grid[r][-1] for r in range(h)])
    for a in left:
